import React, { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { ArrowLeft, ArrowRight, CalendarDays, Check, ChevronRight, Clock3, Flag, MapPin, Medal, Radio, RotateCcw, Save, Search, Shield, Star, Target, Trophy, Users, X } from 'lucide-react';
import { tournamentCatalog, demoTournamentSlug } from '../data/tournamentDemo';
import { getGroupStandings, resolveTournamentMatches, getTournamentStats, updateTournamentMatch, getMatchWinner } from '../lib/tournamentEngine';
import { loadTournamentDraft, saveTournamentDraft, resetTournamentDraft } from '../lib/tournamentStorage';
import TournamentShareTools from '../components/TournamentShareTools';
import './TournamentCenter.css';

const TABS = [['', 'Przegląd'], ['mecze', 'Mecze'], ['grupy', 'Grupy'], ['drabinka', 'Drabinka'], ['statystyki', 'Statystyki'], ['druzyny', 'Drużyny'], ['organizator', 'Organizator']];
const STAGES = { group: 'Faza grupowa', quarterfinal: 'Ćwierćfinały', semifinal: 'Półfinały', third: 'O 3. miejsce', final: 'Finał', playoff: 'Baraż' };
const MATCH_STATUS = { scheduled: 'Nadchodzący', live: 'Na żywo', finished: 'Zakończony' };
const EVENT_TYPES = { goal: 'Gol', assist: 'Asysta', yellow: 'Żółta kartka', red: 'Czerwona kartka' };
const dateLabel = date => { const value = new Date(`${String(date).slice(0, 10)}T12:00:00+01:00`); return Number.isNaN(value.getTime()) ? 'Data do potwierdzenia' : new Intl.DateTimeFormat('pl-PL', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Warsaw' }).format(value); };
const timeLabel = date => date && !Number.isNaN(new Date(date).getTime()) ? new Intl.DateTimeFormat('pl-PL', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Warsaw' }).format(new Date(date)) : 'Brak godziny';
const normalize = value => String(value || '').toLocaleLowerCase('pl').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ł/g, 'l');
const teamFor = (tournament, id) => tournament.teams.find(team => team.id === id);
const sourceLabel = (source, tournament) => {
  if (!source) return 'Do ustalenia';
  if (source.type === 'group') return `${source.position}. miejsce · ${tournament?.groups?.find(group => group.id === source.groupId)?.name || 'grupa'}`;
  const matchIndex = tournament?.matches?.findIndex(match => match.id === source.matchId) ?? -1;
  return `${source.type === 'loser' ? 'Przegrany' : 'Zwycięzca'} meczu ${matchIndex >= 0 ? matchIndex + 1 : 'poprzedniej rundy'}`;
};
const matchGroupLabel = (tournament, match) => tournament.groups.find(group => group.id === match.groupId)?.name || 'Faza grupowa';
const rulesLabel = tournament => {
  const labels = { points: 'punkty', headToHead: 'mecze bezpośrednie', 'head-to-head': 'mecze bezpośrednie', goalDifference: 'bilans bramek', 'goal-difference': 'bilans bramek', goalsScored: 'bramki zdobyte', 'goals-for': 'bramki zdobyte' };
  const rules = tournament.rules?.tiebreakers || ['points', ...(tournament.rules?.tieBreakers || ['head-to-head', 'goal-difference', 'goals-for'])];
  return rules.map(rule => labels[rule.id || rule] || rule.id || rule).join(' → ');
};
const favoriteKey = slug => `mlpn-tournament-favorite-v1:${slug}`;
const TournamentNavigation = createContext({ basePath: '/turnieje', slug: '', onNavigate: () => {} });

function TournamentLink({ section = '', children, className, title }) {
  const { basePath, slug, onNavigate } = useContext(TournamentNavigation);
  const route = [slug, section].filter(Boolean).join('/');
  return <a href={`${basePath.replace(/\/$/, '')}/${route}`} className={className} title={title} onClick={event => {
    if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    event.preventDefault(); onNavigate(route || 'home');
  }}>{children}</a>;
}

function PlayerLink({ playerId, children }) {
  return playerId ? <TournamentLink section={`zawodnik/${encodeURIComponent(playerId)}`} className="tc-player-link">{children}</TournamentLink> : children;
}

function TeamMark({ team, small = false }) {
  const [failed, setFailed] = useState(false);
  return <span className={`tc-team-mark${small ? ' is-small' : ''}`} aria-hidden="true">{team?.logo && !failed ? <img src={team.logo} alt="" onError={() => setFailed(true)} /> : team ? <b>{(team.shortName || team.name).split(' ').map(word => word[0]).slice(0, 3).join('')}</b> : <Shield size={small ? 15 : 21} />}</span>;
}

function TeamName({ tournament, teamId, source, small = false }) {
  const team = teamFor(tournament, teamId);
  const content = <><TeamMark team={team} small={small} /><span>{team?.name || sourceLabel(source, tournament)}</span></>;
  return team ? <TournamentLink section={`druzyna/${encodeURIComponent(team.id)}`} className="tc-team-name" title={`Profil drużyny ${team.name}`}>{content}</TournamentLink> : <span className="tc-team-name">{content}</span>;
}

function MatchScore({ match }) {
  const hasScore = match.homeScore !== null && match.homeScore !== undefined && match.awayScore !== null && match.awayScore !== undefined;
  return <span className="tc-score"><strong>{hasScore ? `${match.homeScore} : ${match.awayScore}` : '— : —'}</strong>{match.homePenalties != null && match.awayPenalties != null && <small>k. {match.homePenalties} : {match.awayPenalties}</small>}</span>;
}

function MatchRow({ tournament, match, featured = false }) {
  const winner = getMatchWinner(match);
  return <article className={`tc-match${match.status === 'live' ? ' is-live' : ''}${featured ? ' is-featured' : ''}`}>
    <div className="tc-match-meta"><span className={`tc-match-status is-${match.status}`}>{match.status === 'live' && <Radio size={12} />}{tournament.isImported && !tournament.isLocalCopy && match.status === 'scheduled' ? 'Brak wyniku w archiwum' : MATCH_STATUS[match.status]}</span><span>{match.stage === 'group' ? matchGroupLabel(tournament, match) : match.stageLabel || STAGES[match.stage]} · {tournament.isImported && match.kickoff ? dateLabel(match.kickoff) + ' · ' : ''}{timeLabel(match.kickoff)}</span>{match.court && <span>{match.court}</span>}</div>
    <div className="tc-match-scoreline"><span className={winner === match.homeTeamId ? 'is-winner' : ''}><TeamName tournament={tournament} teamId={match.homeTeamId} source={match.homeSource} /></span><TournamentLink section={'mecz/' + encodeURIComponent(match.id)} className="tc-score-link" title="Otwórz szczegóły meczu"><MatchScore match={match} /></TournamentLink><span className={winner === match.awayTeamId ? 'is-winner' : ''}><TeamName tournament={tournament} teamId={match.awayTeamId} source={match.awaySource} /></span></div>
    {match.outcomeNote && <p className="tc-match-note">{match.outcomeNote}</p>}
    {!!match.events?.length && <details className="tc-match-events"><summary>Protokół meczu <span>{match.events.length} zdarzeń</span></summary><ul>{[...match.events].sort((a, b) => Number(a.minute) - Number(b.minute)).map(event => {
      const team = teamFor(tournament, event.teamId); const player = team?.players?.find(person => person.id === event.playerId);
      return <li key={event.id}><time>{event.minute == null ? 'Brak minuty' : event.minute + '′'}</time><span className={`tc-event-dot is-${event.type}`} /><span><b><PlayerLink playerId={player?.id}>{player?.name || 'Zawodnik nieustalony'}</PlayerLink></b><small>{team?.name}</small></span><em>{EVENT_TYPES[event.type]}</em></li>;
    })}</ul></details>}
  </article>;
}

function EmptyState({ title, children, icon: Icon = CalendarDays }) {
  return <div className="tc-empty"><Icon size={30} aria-hidden="true" /><h3>{title}</h3><p>{children}</p></div>;
}

function SectionHeading({ eyebrow, title, children }) {
  return <div className="tc-section-heading"><div>{eyebrow && <span className="tc-eyebrow">{eyebrow}</span>}<h2>{title}</h2></div>{children}</div>;
}

function GroupTable({ tournament, group }) {
  const rows = getGroupStandings(tournament, group.id);
  const advancing = group.advancing ?? (tournament.isDemo ? tournament.rules?.advancing || 2 : 0);
  const qualified = new Set(group.qualifiedPositions || Array.from({ length: advancing }, (_, index) => index + 1));
  return <section className="tc-group"><div className="tc-group-heading"><h3>{group.name || `Grupa ${group.id}`}</h3><span>{advancing ? 'Awans bezpośredni: ' + advancing : 'Tabela grupy'}{group.playoffPositions?.length ? ' · dodatkowo baraż' : ''}</span></div><div className="tc-table-scroll"><table><thead><tr><th scope="col">#</th><th scope="col">Drużyna</th><th scope="col"><abbr title="Mecze">M</abbr></th><th scope="col"><abbr title="Bramki">B</abbr></th><th scope="col"><abbr title="Bilans bramek">+/−</abbr></th><th scope="col"><abbr title="Punkty">PKT</abbr></th></tr></thead><tbody>{rows.map(row => <tr key={row.teamId} className={qualified.has(row.position) ? 'is-qualified' : group.playoffPositions?.includes(row.position) ? 'is-playoff' : ''}><td>{row.position}</td><th scope="row"><TeamName tournament={tournament} teamId={row.teamId} small />{row.live && <span className="tc-table-live">LIVE</span>}{row.tied && <span className="tc-table-tied" title="Równość kryteriów sportowych — kolejność wymaga rozstrzygnięcia">ex aequo</span>}</th><td>{row.played}</td><td>{row.goalsFor}:{row.goalsAgainst}</td><td>{row.goalDifference > 0 ? '+' : ''}{row.goalDifference}</td><td><b>{row.points}</b></td></tr>)}</tbody></table></div></section>;
}

function Groups({ tournament }) {
  if (!tournament.groups.length) return <EmptyState title="Grupy poznamy po losowaniu" icon={Users}>Lista zgłoszeń i podział na grupy pojawią się po zatwierdzeniu przez organizatora.</EmptyState>;
  return <><SectionHeading eyebrow="Pierwszy etap" title="Tabele grupowe"><span className="tc-note">Tabela uwzględnia wyniki LIVE. Awans po zakończeniu grupy.</span></SectionHeading><div className="tc-group-phases">{[...new Set(tournament.groups.map(group => group.phaseName || 'Faza grupowa'))].map(phase => <section key={phase}>{new Set(tournament.groups.map(group => group.phaseName)).size > 1 && <h3 className="tc-phase-heading">{phase}</h3>}<div className="tc-groups">{tournament.groups.filter(group => (group.phaseName || 'Faza grupowa') === phase).map(group => <GroupTable key={group.id} tournament={tournament} group={group} />)}</div></section>)}</div><p className="tc-explanation">Kolejność: {rulesLabel(tournament)}. W archiwum brakujący wynik nie jest traktowany jako remis; szczegóły pochodzą z zachowanych danych źródłowych.</p></>;
}

function Bracket({ tournament, matches }) {
  const stages = ['quarterfinal', 'semifinal', 'final'].filter(stage => matches.some(match => match.stage === stage));
  if (!matches.some(match => match.stage !== 'group')) return <EmptyState title="Drabinka czeka na format turnieju" icon={Trophy}>Po ustaleniu liczby drużyn pokażemy ścieżkę od grup aż do finału.</EmptyState>;
  return <><SectionHeading eyebrow="Droga po puchar" title="Drabinka turnieju"><span className="tc-note">{tournament.isImported ? 'Zachowana obsada rund ze źródła. Zobacz uwagi do importu.' : 'Drużyny awansują automatycznie po zakończeniu poprzedniego etapu.'}</span></SectionHeading><div className="tc-bracket-scroll" role="region" aria-label="Drabinka turnieju — przewijaj w poziomie" tabIndex={0}><div className="tc-bracket">{stages.map((stage, index) => <section key={stage} className={`tc-bracket-stage stage-${index}`}><h3><span>0{index + 1}</span>{STAGES[stage]}</h3><div className="tc-bracket-matches">{matches.filter(match => match.stage === stage).map(match => <div className="tc-bracket-slot" key={match.id}><MatchRow tournament={tournament} match={match} /></div>)}</div>{stage === 'final' && matches.filter(match => match.stage === 'third').map(match => <div className="tc-bronze" key={match.id}><h3>O trzecie miejsce</h3><MatchRow tournament={tournament} match={match} /></div>)}</section>)}</div></div>{matches.some(match => match.stage === 'playoff') && <section className="tc-playoff-matches"><SectionHeading title="Baraże" /><div className="tc-match-list">{matches.filter(match => match.stage === 'playoff').map(match => <MatchRow key={match.id} tournament={tournament} match={match} />)}</div></section>}<p className="tc-explanation">Remis w fazie pucharowej rozstrzygają rzuty karne. Wynik serii zapisujemy osobno — nie zwiększa liczby bramek w statystykach.</p></>;
}

function Schedule({ tournament, matches, favorite }) {
  const [teamId, setTeamId] = useState('all'); const [stage, setStage] = useState('all'); const [status, setStatus] = useState('all');
  if (!matches.length) return <EmptyState title="Terminarz jest w przygotowaniu" icon={Clock3}>Godziny, boisko i kolejność spotkań zostaną podane po zamknięciu zgłoszeń.</EmptyState>;
  const visible = matches.filter(match => (teamId === 'all' || match.homeTeamId === teamId || match.awayTeamId === teamId) && (stage === 'all' || match.stage === stage) && (status === 'all' || match.status === status));
  return <><SectionHeading eyebrow="Plan dnia" title="Mecze i wyniki"><span className="tc-note">Godziny w czasie polskim.</span></SectionHeading><div className="tc-filters"><label>Drużyna<select value={teamId} onChange={event => setTeamId(event.target.value)}><option value="all">Wszystkie drużyny</option>{tournament.teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}</select></label><label>Etap<select value={stage} onChange={event => setStage(event.target.value)}><option value="all">Wszystkie etapy</option>{Object.entries(STAGES).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></label><label>Status<select value={status} onChange={event => setStatus(event.target.value)}><option value="all">Wszystkie mecze</option>{Object.entries(MATCH_STATUS).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></label>{favorite && <button className="tc-text-button" onClick={() => setTeamId(favorite)}><Star size={15} />Moja drużyna</button>}</div><div className="tc-result-count">{visible.length} {visible.length === 1 ? 'spotkanie' : 'spotkań'}</div><div className="tc-match-list">{visible.map(match => <MatchRow key={match.id} tournament={tournament} match={match} />)}</div>{!visible.length && <EmptyState title="Brak meczów dla tych filtrów">Zmień drużynę, etap lub status, aby zobaczyć inne spotkania.</EmptyState>}</>;
}

function Statistics({ tournament, stats }) {
  const [category, setCategory] = useState(() => tournament.isImported && !stats.scorers?.length && !stats.assists?.length ? 'teams' : 'scorers');
  const choices = [['teams', 'Drużyny', 'goals', 'Bramki'], ['scorers', 'Strzelcy', 'goals', 'Gole'], ['assists', 'Asystenci', 'assists', 'Asysty'], ['cards', 'Kartki', 'cards', 'Kartki']];
  const resolved = resolveTournamentMatches(tournament);
  const teamTotals = tournament.teams.map(team => {
    const games = resolved.filter(match => ['finished', 'live'].includes(match.status) && Number.isFinite(match.homeScore) && Number.isFinite(match.awayScore) && [match.homeTeamId, match.awayTeamId].includes(team.id));
    return { teamId: team.id, name: team.name, played: games.length, goals: games.reduce((total, match) => total + (match.homeTeamId === team.id ? match.homeScore : match.awayScore), 0), against: games.reduce((total, match) => total + (match.homeTeamId === team.id ? match.awayScore : match.homeScore), 0) };
  }).filter(team => team.played).sort((a, b) => b.goals - a.goals || a.against - b.against || a.name.localeCompare(b.name, 'pl'));
  const selected = choices.find(choice => choice[0] === category);
  const rows = category === 'teams' ? teamTotals : stats[category] || [];
  return <>
    <SectionHeading eyebrow="Liczby turnieju" title="Statystyki turnieju" />
    <div className="tc-stat-bar"><div><b>{stats.played || 0}{stats.live > 0 && <small> + {stats.live} LIVE</small>}</b><span>zakończonych / trwających meczów</span></div><div><b>{stats.goals || 0}</b><span>bramek (w tym LIVE)</span></div><div><b>{Number(stats.averageGoals || 0).toLocaleString('pl-PL', { maximumFractionDigits: 2 })}</b><span>gola na mecz</span></div></div>
    <div className="tc-switch" aria-label="Rodzaj statystyki">{choices.map(([id, label]) => <button key={id} aria-pressed={category === id} onClick={() => setCategory(id)}>{label}</button>)}</div>
    {rows.length ? <div className="tc-ranking"><div className="tc-ranking-heading"><span>{category === 'teams' ? 'Drużyna' : 'Zawodnik / drużyna'}</span><span>{selected[3]}</span></div>{rows.map((row, index) => <div className="tc-ranking-row" key={String(row.playerId) + '-' + row.teamId}><span className="tc-rank-position">{row.rank || row.position || index + 1}</span><TeamMark team={teamFor(tournament, row.teamId)} small /><span><b>{category === 'teams' ? <TournamentLink section={'druzyna/' + encodeURIComponent(row.teamId)}>{row.name}</TournamentLink> : <PlayerLink playerId={row.playerId}>{row.name}</PlayerLink>}</b><small>{category === 'teams' ? row.played + ' meczów · ' + row.against + ' bramek straconych' : teamFor(tournament, row.teamId)?.name}</small></span><strong>{category === 'cards' ? <><span className="tc-yellow">{row.yellow ?? row.yellowCards ?? 0}</span><span className="tc-red">{row.red ?? row.redCards ?? 0}</span></> : row[selected[2]]}</strong></div>)}</div> : <EmptyState title="Brak udokumentowanych zdarzeń" icon={Target}>Źródło nie zawiera tej klasyfikacji. Nie dopisujemy zawodnikom bramek ani asyst na podstawie samego wyniku drużyny.</EmptyState>}
    <p className="tc-explanation">{category === 'teams' ? 'Zestawienie według zdobytych bramek. Obejmuje zapisane wyniki, również LIVE; rzuty karne nie zwiększają bilansu bramek.' : 'Statystyki indywidualne obejmują tylko udokumentowane zdarzenia. Przypisano zawodnikom ' + (stats.recordedGoals || 0) + ' z ' + (stats.goals || 0) + ' bramek. Brakujący protokół nie oznacza, że zawodnik nie wystąpił.'}</p>
  </>;
}

function Teams({ tournament, favorite, setFavorite }) {
  const [search, setSearch] = useState('');
  const visible = tournament.teams.filter(team => normalize(team.name).includes(normalize(search)));
  return <><SectionHeading eyebrow="Uczestnicy" title="Drużyny"><span className="tc-note">Wybierz drużynę, aby szybciej znaleźć jej mecze.</span></SectionHeading>{!tournament.teams.length ? <EmptyState title="Lista uczestników wkrótce" icon={Users}>Na ten moment potwierdzone są data i miejscowość. Zgłoszone zespoły dodamy po otrzymaniu listy od organizatora.</EmptyState> : <><label className="tc-search"><Search size={17} /><input type="search" aria-label="Szukaj drużyny" placeholder="Szukaj drużyny…" value={search} onChange={event => setSearch(event.target.value)} /></label><div className="tc-team-list">{visible.map(team => <article key={team.id}><div className="tc-team-card-head"><TeamName tournament={tournament} teamId={team.id} /><button className={`tc-follow${favorite === team.id ? ' is-followed' : ''}`} aria-pressed={favorite === team.id} aria-label={`${favorite === team.id ? 'Usuń wybór drużyny' : 'Wybierz drużynę'} ${team.name}`} onClick={() => setFavorite(favorite === team.id ? '' : team.id)}><Star size={17} fill={favorite === team.id ? 'currentColor' : 'none'} /><span>{favorite === team.id ? 'Moja drużyna' : 'Wybierz'}</span></button></div><div className="tc-team-card-meta"><span>{tournament.groups.find(group => group.teamIds.includes(team.id))?.name || 'Bez grupy'}</span><span>{team.players?.length || 0} zawodników w kadrze</span></div>{!!team.players?.length && <details><summary>Kadra drużyny</summary><ul className="tc-roster">{team.players.map(player => <li key={player.id}><span>{player.number || '—'}</span><PlayerLink playerId={player.id}>{player.name}</PlayerLink></li>)}</ul></details>}</article>)}</div>{!visible.length && <p className="tc-explanation">Nie znaleziono drużyny o tej nazwie.</p>}{!!tournament.unassignedPlayers?.length && <section className="tc-unassigned"><SectionHeading eyebrow="Zachowane wpisy źródłowe" title="Zawodnicy bez ustalonej drużyny" /><p className="tc-explanation">Te osoby były w źródle, ale przypisane drużyny nie występują już w archiwalnym katalogu.</p><ul className="tc-roster">{tournament.unassignedPlayers.map(player => <li key={player.id}><span>—</span><PlayerLink playerId={player.id}>{player.name}</PlayerLink></li>)}</ul></section>}</>}</>;
}

function MatchEditor({ tournament, match, onSave }) {
  const [form, setForm] = useState({ status: match.status, homeScore: match.homeScore ?? '', awayScore: match.awayScore ?? '', homePenalties: match.homePenalties ?? '', awayPenalties: match.awayPenalties ?? '' });
  const [events, setEvents] = useState(match.events || []); const [error, setError] = useState('');
  const teams = [teamFor(tournament, match.homeTeamId), teamFor(tournament, match.awayTeamId)].filter(Boolean);
  const [eventDraft, setEventDraft] = useState({ type: 'goal', teamId: teams[0]?.id || '', playerId: teams[0]?.players?.[0]?.id || '', minute: '1' });
  const change = (key, value) => setForm(current => ({ ...current, [key]: value }));
  const draftTeam = teams.find(team => team.id === eventDraft.teamId);
  const addEvent = () => {
    if (!eventDraft.teamId || !eventDraft.playerId || !Number.isInteger(Number(eventDraft.minute)) || Number(eventDraft.minute) < 0 || eventDraft.minute === '') { setError('Wybierz zawodnika i podaj prawidłową minutę zdarzenia.'); return; }
    setEvents(current => [...current, { ...eventDraft, minute: Number(eventDraft.minute), id: `event-${Date.now()}-${Math.random().toString(36).slice(2, 8)}` }]); setError('');
  };
  const submit = event => {
    event.preventDefault();
    const hasRecordedData = ['homeScore', 'awayScore', 'homePenalties', 'awayPenalties'].some(key => form[key] !== '') || events.length > 0;
    if (form.status === 'scheduled' && hasRecordedData) {
      setError('Zmień status na Na żywo lub Zakończony, aby zapisać wynik i zdarzenia. Jeśli cofasz mecz do Nadchodzący, najpierw wyczyść wynik i protokół poniższym przyciskiem.');
      return;
    }
    const numberOrNull = value => value === '' ? null : Number(value);
    try { onSave(match.id, { ...form, homeScore: numberOrNull(form.homeScore), awayScore: numberOrNull(form.awayScore), homePenalties: numberOrNull(form.homePenalties), awayPenalties: numberOrNull(form.awayPenalties), events }); setError(''); } catch (saveError) { setError(saveError.message); }
  };
  if (teams.length !== 2) return <EmptyState title="Najpierw rozstrzygnij poprzedni etap" icon={Flag}>Uczestnicy tego meczu wynikają z tabel grupowych lub wcześniejszej rundy. Po ich ustaleniu będzie można wpisać wynik.</EmptyState>;
  return <form className="tc-editor" onSubmit={submit}><div className="tc-editor-title"><span className="tc-eyebrow">{STAGES[match.stage]} · {timeLabel(match.kickoff)}</span><h3>{teams[0].name} <span>—</span> {teams[1].name}</h3></div><div className="tc-editor-score"><label>Status meczu<select value={form.status} onChange={event => change('status', event.target.value)}>{Object.entries(MATCH_STATUS).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></label><label>Gole: {teams[0].name}<input type="number" min="0" step="1" inputMode="numeric" value={form.homeScore} onChange={event => change('homeScore', event.target.value)} /></label><label>Gole: {teams[1].name}<input type="number" min="0" step="1" inputMode="numeric" value={form.awayScore} onChange={event => change('awayScore', event.target.value)} /></label></div>{match.stage !== 'group' && <div className="tc-editor-penalties"><p>Rzuty karne — uzupełnij tylko przy remisie.</p><label>Karne: {teams[0].name}<input type="number" min="0" step="1" value={form.homePenalties} onChange={event => change('homePenalties', event.target.value)} /></label><label>Karne: {teams[1].name}<input type="number" min="0" step="1" value={form.awayPenalties} onChange={event => change('awayPenalties', event.target.value)} /></label></div>}{form.status === 'scheduled' && (form.homeScore !== '' || form.awayScore !== '' || form.homePenalties !== '' || form.awayPenalties !== '' || events.length > 0) && <div className="tc-scheduled-warning"><p>Nadchodzący mecz nie może mieć wyniku ani protokołu. Aby zachować wpisane dane, wybierz status Na żywo lub Zakończony. Cofnięcie meczu usuwa wynik i zdarzenia; może też wycofać awans i wyniki zależnych spotkań.</p><button type="button" className="tc-danger" onClick={() => { setForm(current => ({ ...current, homeScore: '', awayScore: '', homePenalties: '', awayPenalties: '' })); setEvents([]); setError(''); }}>Wyczyść wynik i protokół</button><small>Wyczyszczenie zatwierdzisz przyciskiem „Zapisz mecz lokalnie”.</small></div>}<div className="tc-editor-events"><h4>Protokół / statystyki indywidualne</h4><p>Dodaj zdarzenia i zapisz je razem z wynikiem. Liczba przypisanych goli nie może przekraczać wyniku drużyny.</p><div className="tc-event-form"><label>Zdarzenie<select value={eventDraft.type} onChange={event => setEventDraft(current => ({ ...current, type: event.target.value }))}>{Object.entries(EVENT_TYPES).map(([id, label]) => <option key={id} value={id}>{label}</option>)}</select></label><label>Drużyna zdarzenia<select value={eventDraft.teamId} onChange={event => setEventDraft(current => ({ ...current, teamId: event.target.value, playerId: teams.find(team => team.id === event.target.value)?.players?.[0]?.id || '' }))}>{teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}</select></label><label>Zawodnik<select value={eventDraft.playerId} onChange={event => setEventDraft(current => ({ ...current, playerId: event.target.value }))}>{!draftTeam?.players?.length && <option value="">Brak zawodników</option>}{draftTeam?.players?.map(player => <option key={player.id} value={player.id}>{player.name}</option>)}</select></label><label>Minuta<input type="number" min="0" step="1" value={eventDraft.minute} onChange={event => setEventDraft(current => ({ ...current, minute: event.target.value }))} /></label><button type="button" className="tc-secondary" onClick={addEvent}>Dodaj zdarzenie</button></div><ul className="tc-editor-event-list">{events.map(event => <li key={event.id}><span>{event.minute == null ? 'Brak minuty' : event.minute + '′'}</span><b>{EVENT_TYPES[event.type]}</b><span>{teamFor(tournament, event.teamId)?.players?.find(player => player.id === event.playerId)?.name || 'Zawodnik nieustalony'}</span><button type="button" aria-label={`Usuń zdarzenie ${event.minute} minuta ${EVENT_TYPES[event.type]}`} onClick={() => setEvents(current => current.filter(item => item.id !== event.id))}><X size={15} /></button></li>)}</ul></div>{error && <div className="tc-error" role="alert">{error}</div>}<div className="tc-editor-actions"><p>Zapis zmieni też tabele, statystyki i uczestników kolejnych rund.</p><button className="tc-primary" type="submit"><Save size={17} />Zapisz mecz lokalnie</button></div></form>;
}

function Organizer({ tournament, matches, onSave, onReset, onCreateCopy, revision }) {
  const [selected, setSelected] = useState(matches.find(match => match.status === 'live')?.id || matches[0]?.id || ''); const [confirmReset, setConfirmReset] = useState(false);
  if (tournament.isImported && !tournament.isLocalCopy) return <div className="tc-test-copy"><h3>Przetestuj obsługę na kopii turnieju</h3><p>Wyniki źródłowe pozostaną zachowane. Zmiany w kopii zapiszą się tylko w tej przeglądarce; możesz w każdej chwili przywrócić oryginalny przebieg.</p><button className="tc-primary" onClick={onCreateCopy}>Utwórz kopię do testów <ArrowRight size={16} /></button></div>;
  if (!tournament.isDemo && !tournament.isLocalCopy) return <EmptyState title="Najpierw przygotujemy zgłoszenia i zasady" icon={Shield}>Panel edycji jest teraz dostępny dla osobnego turnieju testowego. Rzeczywisty turniej w Halinowie nie otrzymuje fikcyjnych wyników.</EmptyState>;
  const current = matches.find(match => match.id === selected) || matches[0];
  return <><SectionHeading eyebrow="Stanowisko organizatora" title="Obsługa meczów"><span className="tc-note">Zmiany zapisują się wyłącznie w tej przeglądarce.</span></SectionHeading><label className="tc-match-picker">Wybierz mecz<select value={current?.id || ''} onChange={event => setSelected(event.target.value)}>{matches.map(match => <option key={match.id} value={match.id}>{tournament.isImported && match.kickoff ? dateLabel(match.kickoff) + ' · ' : ''}{timeLabel(match.kickoff)} · {match.stageLabel || STAGES[match.stage]} · {teamFor(tournament, match.homeTeamId)?.name || sourceLabel(match.homeSource, tournament)} — {teamFor(tournament, match.awayTeamId)?.name || sourceLabel(match.awaySource, tournament)}</option>)}</select></label>{current && <MatchEditor key={`${current.id}-${revision}`} tournament={tournament} match={current} onSave={onSave} />}<div className="tc-reset"><div><b>Powrót do danych przykładowych</b><p>Usuwa lokalnie wpisane wyniki i zdarzenia z tego turnieju testowego.</p></div>{confirmReset ? <div className="tc-reset-confirm"><button className="tc-secondary" onClick={() => setConfirmReset(false)}>Anuluj</button><button className="tc-danger" onClick={() => { onReset(); setConfirmReset(false); }}>Tak, przywróć dane</button></div> : <button className="tc-text-button" onClick={() => setConfirmReset(true)}><RotateCcw size={15} />Przywróć przykład</button>}</div></>;
}

function Overview({ tournament, matches, stats, favorite, navigate }) {
  const current = matches.find(match => match.status === 'live') || (!tournament.isImported && matches.find(match => match.status === 'scheduled' && match.homeTeamId && match.awayTeamId)) || matches.find(match => match.stage === 'final' && match.status === 'finished') || [...matches].reverse().find(match => match.status === 'finished');
  const championId = getMatchWinner(matches.find(match => match.stage === 'final'));
  const favoriteMatches = favorite ? matches.filter(match => match.homeTeamId === favorite || match.awayTeamId === favorite).slice(0, 3) : [];
  return <>{championId && <div className="tc-champion"><Trophy size={23} /><div><span>Zwycięzca turnieju</span><TeamName tournament={tournament} teamId={championId} /></div><TournamentLink section="drabinka">Zobacz drogę po puchar <ArrowRight size={14} /></TournamentLink></div>}<div className="tc-overview-grid"><div><SectionHeading eyebrow={current?.status === 'live' ? 'Teraz trwa' : 'Centrum meczowe'} title={current?.status === 'live' ? 'Trwa mecz' : current?.status === 'finished' ? (current.stage === 'final' ? 'Finał turnieju' : 'Ostatni zapisany wynik') : 'Najbliższe spotkanie'} />{current ? <MatchRow tournament={tournament} match={current} featured /> : <EmptyState title="20 grudnia spotykamy się w Halinowie">Godzina rozpoczęcia, dokładna hala, zgłoszenia i regulamin czekają na potwierdzenie.</EmptyState>}<button className="tc-text-button tc-all-matches" onClick={() => navigate('mecze')}>Cały terminarz <ArrowRight size={16} /></button></div><aside className="tc-format-summary"><span className="tc-eyebrow">Wokół turnieju</span><h3>{tournament.isDemo ? 'Jeden dzień. Jeden puchar.' : tournament.isImported ? 'Turniej zapisany w historii.' : 'Gramy pod dachem.'}</h3><p>{tournament.description}</p><dl><div><dt><Users size={15} />Drużyny</dt><dd>{tournament.teams.length || 'Lista wkrótce'}</dd></div><div><dt><Flag size={15} />Grupy</dt><dd>{tournament.groups.length || 'Po losowaniu'}</dd></div><div><dt><CalendarDays size={15} />Data</dt><dd>{dateLabel(tournament.date)}</dd></div><div><dt><MapPin size={15} />Miejsce</dt><dd>{tournament.location}</dd></div></dl></aside></div>{!!matches.length && <div className="tc-stat-bar"><div><b>{stats.played || 0}<small> / {matches.length}</small></b><span>meczów zakończonych</span></div><div><b>{stats.goals || 0}</b><span>bramek w turnieju</span></div><div><b>{matches.filter(match => match.stage !== 'group').length}</b><span>meczów o awans i medale</span></div></div>}{favoriteMatches.length > 0 && <section className="tc-favorite-matches"><SectionHeading eyebrow="Moja drużyna" title={teamFor(tournament, favorite)?.name} /><div className="tc-match-list">{favoriteMatches.map(match => <MatchRow key={match.id} tournament={tournament} match={match} />)}</div></section>}<div className="tc-shortcuts">{[['grupy', 'Od pierwszego punktu', 'Grupy i awans', Users], ['drabinka', 'Do ostatniego gwizdka', 'Droga do finału', Trophy], ['statystyki', 'Wyróżniają się w turnieju', 'Strzelcy i statystyki', Target]].map(([id, kicker, label, Icon]) => <button key={id} onClick={() => navigate(id)}><Icon size={22} /><span><small>{kicker}</small><b>{label}</b></span><ChevronRight size={19} /></button>)}</div></>;
}

function TournamentProfile({ tournament, matches, type, id, navigate }) {
  if (type === 'mecz') return <MatchProfile tournament={tournament} match={matches.find(item => item.id === id)} navigate={navigate} />;
  const unassigned = tournament.unassignedPlayers?.find(player => player.id === id);
  if (type === 'zawodnik' && unassigned) return <><button className="tc-text-button" onClick={() => navigate('druzyny')}><ArrowLeft size={15} />Drużyny i kadry</button><header className="tc-profile-heading"><div className="tc-player-avatar"><Users size={30} /></div><div><span className="tc-eyebrow">Zawodnik z archiwum źródłowego</span><h2>{unassigned.name}</h2><p>Drużyna nie jest dostępna w zachowanym katalogu turnieju.</p></div></header><EmptyState title="Niepełny historyczny profil" icon={Users}>Zachowaliśmy wpis zawodnika ze źródła. Jego dawne przypisanie wskazuje zespół, którego już nie ma w archiwum. Nie przenosimy go do innej drużyny i nie dopisujemy mu występów.</EmptyState></>;
  const isTeam = type === 'druzyna';
  const team = isTeam ? teamFor(tournament, id) : tournament.teams.find(item => item.players?.some(player => player.id === id));
  const player = !isTeam && team?.players?.find(item => item.id === id);
  if (!team || (!isTeam && !player)) return <><button className="tc-text-button tc-profile-jump" onClick={() => navigate(isTeam ? 'druzyny' : 'statystyki')}><ArrowLeft size={15} />Wróć do zestawienia</button><EmptyState title={isTeam ? 'Nie znaleziono drużyny' : 'Nie znaleziono zawodnika'}>Tego wpisu nie ma w danych wybranego turnieju.</EmptyState></>;
  const teamMatches = matches.filter(match => match.homeTeamId === team.id || match.awayTeamId === team.id);
  const completed = teamMatches.filter(match => match.status === 'finished' && Number.isFinite(match.homeScore) && Number.isFinite(match.awayScore));
  const totals = completed.reduce((result, match) => {
    const home = match.homeTeamId === team.id; const goals = home ? match.homeScore : match.awayScore; const against = home ? match.awayScore : match.homeScore;
    return { goals: result.goals + goals, against: result.against + against, wins: result.wins + (getMatchWinner(match) === team.id ? 1 : 0) };
  }, { goals: 0, against: 0, wins: 0 });
  const playerMatches = teamMatches.filter(match => match.events?.some(event => event.playerId === player?.id));
  const playerEvents = teamMatches.filter(match => ['finished', 'live'].includes(match.status)).flatMap(match => match.events || []).filter(event => event.playerId === player?.id);
  const goals = playerEvents.filter(event => event.type === 'goal').length; const assists = playerEvents.filter(event => event.type === 'assist').length;
  const groups = tournament.groups.filter(group => group.teamIds.includes(team.id));
  return <>
    <button className="tc-text-button tc-profile-jump" onClick={() => navigate(isTeam ? 'druzyny' : 'statystyki')}><ArrowLeft size={15} />{isTeam ? 'Wszystkie drużyny' : 'Statystyki turnieju'}</button>
    <header className="tc-profile-heading">{isTeam ? <TeamMark team={team} /> : <div className="tc-player-avatar">{player.number || <Users size={30} />}</div>}<div><span className="tc-eyebrow">{isTeam ? 'Profil drużyny' : 'Profil zawodnika'} · {tournament.name}</span><h2>{isTeam ? team.name : player.name}</h2>{isTeam ? <p>{groups.map(group => [group.phaseName, group.name].filter(Boolean).join(' · ')).join(' / ') || 'Uczestnik turnieju'}</p> : <TeamName tournament={tournament} teamId={team.id} small />}</div></header>
    <div className="tc-stat-bar">{isTeam ? <><div><b>{completed.length}</b><span>meczów z wynikiem</span></div><div><b>{totals.goals}:{totals.against}</b><span>bramki zdobyte / stracone</span></div><div><b>{totals.wins}</b><span>zwycięstw (w tym po karnych)</span></div></> : <><div><b>{goals}</b><span>zapisanych bramek</span></div><div><b>{assists}</b><span>zapisanych asyst</span></div><div><b>{playerMatches.length}</b><span>meczów ze zdarzeniem zawodnika</span></div></>}</div>
    <div className="tc-profile-grid"><section><SectionHeading title={isTeam ? 'Mecze drużyny' : 'Zdarzenia w meczach'} />{(isTeam ? teamMatches : playerMatches).length ? <div className="tc-match-list">{(isTeam ? teamMatches : playerMatches).map(match => <MatchRow key={match.id} tournament={tournament} match={isTeam ? match : { ...match, events: match.events.filter(event => event.playerId === player.id) }} />)}</div> : <EmptyState title="Brak zapisanych zdarzeń">Obecność w kadrze nie oznacza automatycznie występu. Statystyki pokażemy, gdy dostępny będzie protokół meczowy.</EmptyState>}</section><aside className="tc-profile-roster"><h3>{isTeam ? 'Kadra drużyny' : 'Zawodnicy drużyny'}</h3>{team.players?.length ? <ul className="tc-roster">{team.players.map(person => <li key={person.id}><span>{person.number || '—'}</span><PlayerLink playerId={person.id}>{person.name}</PlayerLink></li>)}</ul> : <p className="tc-explanation">Źródło zawiera drużynę i jej wyniki, ale nie zawiera listy zawodników. Nie uzupełniamy jej domysłami.</p>}</aside></div>
    {!isTeam && <p className="tc-explanation">Liczba meczów ze zdarzeniem nie jest liczbą wszystkich występów. Historyczne protokoły mogą nie obejmować zawodników, którzy nie strzelili gola ani nie otrzymali kartki.</p>}
  </>;
}

function MatchProfile({ tournament, match, navigate }) {
  if (!match) return <EmptyState title="Nie znaleziono meczu">Ten identyfikator nie występuje w terminarzu wybranego turnieju.</EmptyState>;
  const teams = [teamFor(tournament, match.homeTeamId), teamFor(tournament, match.awayTeamId)].filter(Boolean);
  return <><button className="tc-text-button tc-profile-jump" onClick={() => navigate('mecze')}><ArrowLeft size={15} />Wszystkie mecze</button><SectionHeading eyebrow={match.stage === 'group' ? matchGroupLabel(tournament, match) : match.stageLabel || STAGES[match.stage]} title="Centrum meczu"><span className="tc-note">{match.kickoff ? dateLabel(match.kickoff) : dateLabel(tournament.date)} · {timeLabel(match.kickoff)}</span></SectionHeading><MatchRow tournament={tournament} match={match} featured /><div className="tc-match-profile-teams">{teams.map(team => <section className="tc-profile-roster" key={team.id}><TeamName tournament={tournament} teamId={team.id} /><h3>Zgłoszona kadra</h3>{team.players?.length ? <ul className="tc-roster">{team.players.map(player => <li key={player.id}><span>{player.number || '—'}</span><PlayerLink playerId={player.id}>{player.name}</PlayerLink></li>)}</ul> : <p className="tc-explanation">Źródło nie zawiera kadry tej drużyny.</p>}</section>)}</div>{!match.events?.length && <p className="tc-explanation">{Number.isFinite(match.homeScore) && Number.isFinite(match.awayScore) ? 'Dostępny jest wynik meczu, ale bez szczegółowego protokołu zdarzeń.' : tournament.isImported ? 'W archiwum brakuje wyniku i szczegółowego protokołu tego meczu.' : 'Wynik i protokół tego meczu nie zostały jeszcze zapisane.'} Lista zgłoszonych zawodników nie potwierdza udziału w tym spotkaniu.</p>}</>;
}

function TournamentDetail({ initial, tab, darkMode, onNavigate, basePath }) {
  const [tournament, setTournament] = useState(() => loadTournamentDraft(initial)); const [revision, setRevision] = useState(0); const [notice, setNotice] = useState('');
  const [favorite, setFavoriteState] = useState(() => { try { return localStorage.getItem(favoriteKey(initial.slug)) || ''; } catch { return ''; } });
  const matches = useMemo(() => resolveTournamentMatches(tournament), [tournament]); const stats = useMemo(() => getTournamentStats(tournament), [tournament]);
  useEffect(() => { const sync = () => { setTournament(loadTournamentDraft(initial)); setRevision(value => value + 1); }; window.addEventListener('storage', sync); return () => window.removeEventListener('storage', sync); }, [initial]);
  const setFavorite = id => { setFavoriteState(id); try { localStorage.setItem(favoriteKey(initial.slug), id); } catch { /* Preferences remain usable for this session. */ } };
  const navigate = section => onNavigate(`${tournament.slug}${section ? `/${section}` : ''}`);
  const save = (matchId, patch) => { const next = updateTournamentMatch(tournament, matchId, patch); const saved = saveTournamentDraft(next); setTournament(next); setRevision(value => value + 1); setNotice(saved ? 'Mecz zapisany lokalnie. Tabele, drabinka i statystyki zostały przeliczone.' : 'Mecz zmieniony w tej sesji. Przeglądarka zablokowała trwały zapis — zmiany mogą zniknąć po odświeżeniu.'); };
  const reset = () => { resetTournamentDraft(initial); setTournament(initial); setRevision(value => value + 1); setNotice(initial.isImported ? 'Przywrócono oryginalny przebieg turnieju ze źródła.' : 'Przywrócono przykładowy przebieg turnieju.'); };
  const [profileType, encodedProfileId] = tab.split('/');
  let profileId = encodedProfileId || ''; try { profileId = decodeURIComponent(profileId); } catch { /* Invalid IDs resolve to an empty state. */ }
  const isProfile = ['druzyna', 'zawodnik', 'mecz'].includes(profileType) && profileId;
  const validTab = isProfile ? (profileType === 'druzyna' ? 'druzyny' : profileType === 'mecz' ? 'mecze' : 'statystyki') : TABS.some(([id]) => id === tab) ? tab : '';
  const createCopy = () => { const copy = { ...tournament, isLocalCopy: true }; const saved = saveTournamentDraft(copy); setTournament(copy); setNotice(saved ? 'Utworzono lokalną kopię. Możesz teraz zmieniać wyniki.' : 'Kopia jest dostępna w tej sesji. Przeglądarka zablokowała trwały zapis.'); };
  return <section className={`tournament-center${darkMode ? ' is-dark' : ''}`}><div className="tc-local-banner"><span className="tc-local-dot" />{tournament.isDemo ? 'TURNIEJ TESTOWY · wyniki i składy przykładowe' : tournament.isLocalCopy ? 'KOPIA TESTOWA · Twoje zmiany w tej przeglądarce' : tournament.isImported ? 'ARCHIWUM · dane odtworzone z Tournify' : 'TURNIEJ W PRZYGOTOWANIU'}<span>Podgląd do testów</span></div><header className="tc-detail-header"><button className="tc-back" onClick={() => onNavigate('home')}><ArrowLeft size={15} />Wszystkie turnieje</button><div className="tc-detail-title"><div><span className="tc-eyebrow">{tournament.isImported ? 'MLPN · Archiwum turniejów' : 'MLPN · Piłka halowa'}</span><h1>{tournament.name}</h1><div className="tc-title-meta"><span><CalendarDays size={15} />{dateLabel(tournament.date)}</span><span><MapPin size={15} />{tournament.location}</span></div></div><span className={`tc-status-badge ${tournament.isDemo ? 'is-demo' : ''}`}>{tournament.isDemo || tournament.isLocalCopy ? 'Wersja do testów' : ['completed', 'archived'].includes(tournament.status) ? 'Archiwalny' : 'Nadchodzący'}</span></div>{tournament.sourceUrl && <p className="tc-source">Źródło archiwum: <a href={tournament.sourceUrl} target="_blank" rel="noopener noreferrer">{tournament.sourceLabel || 'Tournify'} ↗</a>{tournament.sourceIncomplete && <span>· Część historycznych danych jest niepełna.</span>}</p>}</header><nav className="tc-tabs" aria-label="Sekcje turnieju">{TABS.map(([id, label]) => <a href={basePath.replace(/\/$/, '') + '/' + tournament.slug + (id ? '/' + id : '')} aria-current={validTab === id ? 'page' : undefined} key={id} onClick={event => { if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return; event.preventDefault(); navigate(id); }}>{label}</a>)}</nav><div className="tc-content" role="region" aria-label={TABS.find(([id]) => id === validTab)?.[1]}>{!!tournament.sourceNotes?.length && <details className="tc-source-notes"><summary>Źródła i kompletność archiwum</summary><ul>{tournament.sourceNotes.map((note, index) => <li key={index}>{note}</li>)}</ul></details>}{notice && <div className="tc-notice" role="status"><Check size={16} /><span>{notice}</span><button aria-label="Zamknij komunikat" onClick={() => setNotice('')}><X size={15} /></button></div>}{isProfile && <TournamentProfile tournament={tournament} matches={matches} type={profileType} id={profileId} navigate={navigate} />}{!isProfile && validTab === '' && <Overview tournament={tournament} matches={matches} stats={stats} favorite={favorite} navigate={navigate} />}{!isProfile && validTab === 'mecze' && <Schedule tournament={tournament} matches={matches} favorite={favorite} />}{validTab === 'grupy' && <Groups tournament={tournament} />}{validTab === 'drabinka' && <Bracket tournament={tournament} matches={matches} />}{!isProfile && validTab === 'statystyki' && <Statistics tournament={tournament} stats={stats} />}{!isProfile && validTab === 'druzyny' && <Teams tournament={tournament} favorite={favorite} setFavorite={setFavorite} />}{validTab === 'organizator' && <Organizer tournament={tournament} matches={matches} onSave={save} onReset={reset} onCreateCopy={createCopy} revision={revision} />}</div><div className="tc-share-area"><TournamentShareTools tournament={tournament} basePath={basePath} /></div></section>;
}

function ArchiveCatalog({ onNavigate, basePath }) {
  const archives = tournamentCatalog.filter(tournament => tournament.isImported).sort((a, b) => String(b.date).localeCompare(String(a.date)));
  if (!archives.length) return null;
  return <section className="tc-archive-title"><SectionHeading eyebrow="Poprzednie edycje" title="Archiwum turniejów"><span className="tc-note">Rzeczywiste grupy, drabinki i wyniki odtworzone z Tournify.</span></SectionHeading><div className="tc-archive-list">{archives.map(tournament => <article className="tc-archive-row" key={tournament.id}><span className="tc-archive-year">{String(tournament.date || '').slice(0, 4) || '—'}</span><div><h3><a href={`${basePath}/${tournament.slug}`} onClick={event => { if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return; event.preventDefault(); onNavigate(tournament.slug); }}>{tournament.name}</a></h3><div className="tc-archive-meta"><span>{dateLabel(tournament.date)}</span><span>{tournament.teams.length} drużyn</span><span>{tournament.matches.length} meczów</span>{tournament.sourceIncomplete && <span>Niepełne archiwum</span>}</div></div><button className="tc-secondary" onClick={() => onNavigate(tournament.slug)}>Otwórz <ArrowRight size={16} /></button></article>)}</div></section>;
}

function TournamentCatalog({ darkMode, onNavigate, basePath }) {
  const upcoming = tournamentCatalog.find(tournament => !tournament.isDemo && !tournament.isImported && tournament.status === 'upcoming'); const demo = tournamentCatalog.find(tournament => tournament.slug === demoTournamentSlug);
  return <section className={`tournament-center${darkMode ? ' is-dark' : ''}`}><div className="tc-local-banner"><span className="tc-local-dot" />CENTRUM TURNIEJÓW · PODGLĄD<span>Wersja do testów</span></div><header className="tc-catalog-hero"><div className="tc-catalog-copy"><span className="tc-eyebrow">MLPN · Poza ligowym terminarzem</span><h1>Turnieje<span>Całe emocje w jednym miejscu.</span></h1><p>Mecze, grupy, droga po puchar i zawodnicy, którzy robią różnicę. Śledź swój zespół od pierwszego gwizdka.</p>{upcoming && <button className="tc-hero-link" onClick={() => onNavigate(upcoming.slug)}>Najbliższy turniej <ArrowRight size={17} /></button>}</div><div className="tc-court-visual" aria-hidden="true"><div className="tc-court-line" /><div className="tc-court-circle" /><div className="tc-court-goal top" /><div className="tc-court-goal bottom" /><Trophy size={75} strokeWidth={1} /><span>MLPN CUP</span></div></header><div className="tc-content tc-catalog-content"><SectionHeading eyebrow="Zapisz datę" title="Najbliższe wydarzenie" />{upcoming && <article className="tc-upcoming"><div className="tc-calendar"><strong>{new Date(`${upcoming.date}T12:00:00`).getDate()}</strong><span>{new Intl.DateTimeFormat('pl-PL', { month: 'long' }).format(new Date(`${upcoming.date}T12:00:00`))}</span><small>{String(upcoming.date).slice(0, 4)}</small></div><div className="tc-upcoming-copy"><span className="tc-eyebrow">Nadchodzący · halowy</span><h2>{upcoming.name}</h2><p><MapPin size={16} />{upcoming.location}</p><span className="tc-note">Format, lista drużyn i godzina startu w przygotowaniu.</span></div><button className="tc-primary" onClick={() => onNavigate(upcoming.slug)}>Otwórz turniej <ArrowRight size={16} /></button></article>}<ArchiveCatalog onNavigate={onNavigate} basePath={basePath} />{demo && <section className="tc-demo-entry"><div className="tc-demo-label"><Radio size={19} /><span>PLAC TESTOWY</span></div><div><h2>{demo.name}</h2><p>Sprawdź działanie grup, wyników i drabinki. W panelu organizatora możesz rozegrać turniej i od razu zobaczyć, co się zmienia.</p><div className="tc-demo-facts"><span>{demo.teams.length} drużyn</span><span>{demo.groups.length} grupy</span><span>Faza pucharowa</span><span>Lokalny zapis</span></div></div><button className="tc-secondary" onClick={() => onNavigate(demo.slug)}>Otwórz przykład <ArrowRight size={16} /></button></section>}<div className="tc-import-note"><Medal size={22} /><div><h3>Historia turniejów w jednym centrum</h3><p>Archiwalne edycje zachowują źródłowe wyniki. Osobny przykład i lokalne kopie pozwalają bezpiecznie sprawdzać obsługę meczów, grup oraz awansów.</p></div></div></div></section>;
}

export default function TournamentCenter({ darkMode = false, route = 'home', onNavigate = () => {}, basePath = '/turnieje' }) {
  const [slug, ...rest] = String(route || 'home').split('/').filter(Boolean); const tab = rest.join('/');
  if (!slug || slug === 'home') return <TournamentCatalog darkMode={darkMode} onNavigate={onNavigate} basePath={basePath} />;
  const tournament = tournamentCatalog.find(item => item.slug === slug);
  if (!tournament) return <section className={`tournament-center${darkMode ? ' is-dark' : ''}`}><div className="tc-content"><EmptyState title="Nie znaleziono turnieju">Ten adres nie jest dostępny w lokalnym katalogu.</EmptyState><button className="tc-secondary" onClick={() => onNavigate('home')}><ArrowLeft size={16} />Wróć do turniejów</button></div></section>;
  return <TournamentNavigation.Provider value={{ basePath, slug: tournament.slug, onNavigate }}><TournamentDetail key={tournament.slug} initial={tournament} tab={tab} darkMode={darkMode} onNavigate={onNavigate} basePath={basePath} /></TournamentNavigation.Provider>;
}
